info.description:
/* Widen Claude AI chat content area */
/* Target the main content container */
main[class*="flex"][class*="flex-col"],
div[class*="mx-auto"][class*="max-w"] {
    max-width: 90vw !important; /* Use 90% of viewport width */
    width: 100% !important;
}

/* Also target any nested content containers */
div[class*="prose"] {
    max-width: none !important;
}

